   202	    const testing = std.testing;
   203	
   204	    {
   205	        const p: Preedit = .{
   206	            .codepoints = &.{.{ .codepoint = 'a' }},
   207	        };
   208	        const range = p.range(2, 9);
   209	        try testing.expectEqual(@as(terminalpkg.size.CellCountInt, 2), range.start);
   210	        try testing.expectEqual(@as(terminalpkg.size.CellCountInt, 2), range.end);
   211	        try testing.expectEqual(@as(usize, 0), range.cp_offset);
   212	    }
   213	
   214	    {
   215	        const p: Preedit = .{
   216	            .codepoints = &.{.{ .codepoint = test_hangul_ga, .wide = true }},
   217	        };
   218	        const range = p.range(2, 9);
   219	        try testing.expectEqual(@as(terminalpkg.size.CellCountInt, 2), range.start);
   220	        try testing.expectEqual(@as(terminalpkg.size.CellCountInt, 3), range.end);
   221	        try testing.expectEqual(@as(usize, 0), range.cp_offset);
   222	    }
   223	}
